  if(key!==inboxLoadedKey){$('#inbox-summary').textContent='正在查询…';const data=await rpc('messages_query',params);if(request!==inboxRequest||page!=='inbox'||!$('#inbox-search'))return;inboxData=data;inboxPage=data.page;inboxLoadedKey=key;}
  const rows=inboxData.rows;for(const id of inboxSelected)if(!rows.some(m=>m.id===id))inboxSelected.delete(id);
  $('#inbox-summary').textContent=`共 ${inboxData.total} 条 · 待分析 ${state.pending||0} 条 · 自动保留 ${state.config.message_retention_days??90} 天 · 最近读取 ${date(state.last_scan)}`;
  $('#inbox-page-label').textContent=`第 ${inboxPage} / ${inboxData.pages} 页`;
