  setHtml('#inbox-content',rows.length?`<div class="box">${rows.map(m=>`<div class="inbox-row" data-message-key="${esc(m.id)}"><input type="checkbox" aria-label="选择消息" data-inbox-select="${esc(m.id)}" ${inboxSelected.has(m.id)?'checked':''}>${senderAvatar(m.sender)}<div class="inbox-main"><div class="inbox-head"><b class="inbox-sender">${esc(m.sender)}</b>${badge(m.mine?'我发出的':m.private?'私聊':m.mention_me?'@我':m.mention_all?'@全体':'群消息')}<span class="inbox-where">${esc(m.source_name||'历史来源')} · ${esc(m.group)}</span><time class="inbox-time">${esc(date(m.time))}</time></div>${messageBody(m.text||'['+m.kind+']')}${messageImages(m)}<div class="inbox-actions"><button data-build="${esc(m.id)}">补建事项</button><button class="quiet" data-inbox-delete="${esc(m.id)}">删除消息</button></div></div></div>`).join('')}</div>`:empty('没有符合条件的消息','可调整时间或搜索条件。已过期清理的消息不参与查询。'));
