let deletingMessages=[];
function confirmMessageDelete(ids){deletingMessages=ids;setModal(`<h2>删除 ${ids.length} 条消息</h2><p>从消息收件箱和上下文查询中移除这些消息，后续扫描不会再次导入。关联事项及处理记录会保留。</p><div id="modal-error" class="error-box"></div><div class="dialog-foot"><button data-action="close">取消</button><button data-workflow="delete-messages">确认删除</button></div>`);}

const adviceDrafts=new Map(),adviceOpen=new Set(),adviceBusy=new Set();
