function renderLearning(){
 $('#view').dataset.contentPage='prompts';$('#view').dataset.renderedPromptSection='advice';
 const active=document.activeElement,key=active?.dataset.adviceText,caret=key?[active.selectionStart,active.selectionEnd]:null;
 const rows=[...(state.suggestions||[]).filter(r=>!r.archived_at).map(r=>['rule',r]),...(state.tag_state?.proposals||[]).filter(r=>!r.archived_at).map(r=>['tag',r]),...(state.evolution?.prompts||[]).filter(r=>!r.archived_at&&['ready','adopted','rejected','unchanged','superseded'].includes(r.status)&&r.reason?.trim()&&(r.status==='unchanged'||r.proposed_prompt?.trim())).map(r=>['prompt',r]),...(state.evolution?.handling||[]).filter(r=>!r.archived_at).map(r=>['handling',r])].sort((a,b)=>b[1].created-a[1].created),settled=([k,r])=>k==='rule'?['enabled','rejected','integrated'].includes(ruleDecision(r)):k==='handling'?r.adopted||r.rejected:['adopted','rejected','unchanged','superseded'].includes(r.status),pending=rows.filter(([k,r])=>k==='prompt'?r.status==='ready':!settled([k,r])),done=rows.filter(settled);
 setHtml('#view',`<div class="page advice-page">${systemPromptTabs()}<div class="box"><h2>待确认 ${pending.length} 条</h2>${help("保留历史及手动生成的建议；可预览、启用、拒绝或批复。归档不再修改或自动采用提示词。")}<div class="row"><button data-handle="learn">从处置记录生成建议</button><button data-prompt-section="history">提示词与版本</button></div></div>${pending.map(([k,r])=>adviceCard(k,r)).join('')||empty('没有待确认的建议','继续使用和修正事项，有充分依据时会产生新建议。')}${done.length?`<details class="box"><summary>已处理 ${done.length} 条 · 下次归档后收起</summary>${done.map(([k,r])=>adviceCard(k,r)).join('')}</details>`:''}${tagHistory()}</div>`);
 if(key){const el=[...document.querySelectorAll('[data-advice-text]')].find(el=>el.dataset.adviceText===key);if(el){el.focus({preventScroll:true});el.setSelectionRange(...caret);}}
}
let promptTarget='classify',promptEditing=false;
async function renderPromptHistory(){const request=++promptRequest,epoch=renderEpoch;if($('#view').dataset.contentPage!=='prompts'||$('#view').dataset.renderedPromptSection!=='history'){setHtml('#view',`<div class="page prompt-workspace">${systemPromptTabs()}<div class="box">读取系统提示词…</div></div>`);$('#view').dataset.contentPage='prompts';$('#view').dataset.renderedPromptSection='history';}const result=await rpc('prompt_history');if(page!=='prompts'||promptSection!=='history'||epoch!==renderEpoch||request!==promptRequest)return;promptHistory=result;promptEditing=false;renderPromptWorkspace();}
function renderPromptWorkspace(){const result=promptHistory,versions=(result.versions||[]).filter(v=>v.target===promptTarget).slice().reverse(),current=versions.find(v=>v.id===result.current[promptTarget]);setHtml('#view',`<div class="page prompt-workspace">${systemPromptTabs()}<div class="prompt-toolbar"><label>用途 <select id="prompt-target">${Object.entries(promptLabels).map(([k,label])=>`<option value="${k}" ${k===promptTarget?'selected':''}>${label}</option>`).join('')}</select></label>${help('系统提示词仅由你配置；编辑、手动采用和回滚保留版本。固定协议由程序追加，AI 不能修改。')}<span class="tiny">${current?'更新于 '+esc(date(current.created)):''}</span><button data-prompt-edit>编辑</button>${promptTarget==='handling'?'<button data-handle="policy-edit">项目匹配</button><button data-workflow="handling-history">匹配版本</button>':''}</div><section class="prompt-current"><textarea id="prompt-content" readonly spellcheck="false" aria-label="当前提示词" maxlength="20000">${esc(current?.content||'')}</textarea><div class="editor-actions" id="prompt-editor-actions" hidden><button data-prompt-reset>恢复内置</button><button data-prompt-cancel>取消</button><button class="primary" data-prompt-save>保存</button></div><div class="error-box" id="prompt-error"></div></section><details class="prompt-history"><summary>历史版本 · ${versions.length}</summary>${versions.map(v=>`<details class="prompt-version"><summary><span>${esc(date(v.created))}</span><span>${esc({initial:'初始',manual:'编辑',adopt:'采用',auto_adopt:'自动采用',consolidate:'归档',rollback:'回滚'}[v.action]||v.action)}</span>${current?.id===v.id?'<span class="badge">当前</span>':''}</summary><p class="helper">${esc(v.reason||'')}</p><div class="version-compare">${current?.id!==v.id?`<label>当前<textarea readonly rows="8">${esc(current?.content||'')}</textarea></label>`:''}<label>此版本<textarea readonly rows="8">${esc(v.content)}</textarea></label></div>${current?.id!==v.id?`<div class="editor-actions"><button data-prompt-rollback="${esc(v.id)}">回滚到此版本</button></div>`:''}</details>`).join('')}</details></div>`);}
document.addEventListener('change',e=>{if(e.target.id==='prompt-target'){if(promptEditing&&!confirm('放弃当前提示词编辑？')){e.target.value=promptTarget;return;}promptTarget=e.target.value;promptEditing=false;settingsDirty=false;renderPromptWorkspace();}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.hasAttribute('data-prompt-edit')){promptEditing=true;settingsDirty=true;$('#prompt-content').readOnly=false;$('#prompt-editor-actions').hidden=false;b.hidden=true;$('#prompt-content').focus();}
 if(b.hasAttribute('data-prompt-cancel')){promptEditing=false;settingsDirty=false;renderPromptWorkspace();}
 if(b.hasAttribute('data-prompt-reset')){promptDefaults=promptDefaults||await rpc('prompts');if(promptEditing&&$('#prompt-content'))$('#prompt-content').value=promptDefaults[promptTarget]||'';}
 if(b.hasAttribute('data-prompt-save')){const controls=[...$('.prompt-workspace').querySelectorAll('button,select,textarea')];controls.forEach(el=>el.disabled=true);try{await rpc('prompt_save',{target:promptTarget,text:$('#prompt-content').value,expected:promptHistory.current[promptTarget]});promptEditing=false;settingsDirty=false;await refreshState(true);toast('提示词已保存');}finally{controls.forEach(el=>el.disabled=false);}}
 }catch(error){if($('#prompt-error'))$('#prompt-error').textContent=error.message;else toast(error.message);}});


let mergePrimary=null,mergeTarget='',mergeQuery='';
function mergeForm(t){mergePrimary=structuredClone(t);mergeTarget='';mergeQuery='';setModal(`<h2>合并事项</h2><p class="subtitle">保留当前事项，将所选事项的描述和消息依据合并进来。可在操作记录中撤销。</p><div class="merge-current"><span class="tiny">保留的事项</span><b>${esc(t.title)}</b><p>${esc(t.description)}</p><span class="tiny">${esc(t.status)}</span></div><input id="merge-search" aria-label="搜索合并事项" placeholder="搜索标题、描述或标签"><div class="helper" id="merge-count"></div><div id="merge-candidates" class="merge-candidates"></div><div id="merge-environment"></div><div id="modal-error" class="error-box"></div><div class="dialog-foot"><button data-action="close">取消</button><button class="primary" data-action="apply-merge" disabled>确认合并</button></div>`);$('#dialog').classList.add('wide-dialog');renderMergeCandidates();}
function mergeCandidates(){return state.tasks.filter(t=>t.id!==mergePrimary.id&&!t.archived&&!t.merged_into).sort((a,b)=>Number(a.status!=='待处理')-Number(b.status!=='待处理')||b.updated-a.updated);}
function renderMergeCandidates(){const all=mergeCandidates(),q=mergeQuery.trim().toLowerCase(),rows=all.filter(t=>!q||(t.title+' '+t.description+' '+taskTags(t).map(v=>v.kind+' '+v.value).join(' ')).toLowerCase().includes(q));$('#merge-count').textContent=`${all.length} 条可合并事项（不含当前事项） · 搜索结果 ${rows.length} 条`;setHtml('#merge-candidates',rows.map(t=>`<label class="merge-option ${mergeTarget===t.id?'selected':''}"><input type="radio" name="merge-choice" value="${esc(t.id)}" ${mergeTarget===t.id?'checked':''}><span><b>${esc(t.title)}</b><span class="tiny">${esc(t.status)} · ${esc(taskTags(t).map(tag=>tag.kind+' · '+tag.value).join('、'))}</span><p>${esc(t.description||'暂无描述')}</p></span></label>`).join('')||'<p class="helper">没有符合条件的事项</p>');const target=all.find(t=>t.id===mergeTarget);setHtml('#merge-environment','');updateMergeButton();}
function updateMergeButton(){const t=mergeCandidates().find(t=>t.id===mergeTarget);$('[data-action="apply-merge"]').disabled=!t;}
async function applyMerge(){const b=$('[data-action="apply-merge"]');if(b.disabled)return;b.disabled=true;try{await perform('merge',{ids:[mergePrimary.id,mergeTarget]},'已合并，可在操作记录中撤销');closeModal();}catch(e){$('#modal-error').textContent=e.message;updateMergeButton();}}

document.addEventListener('input',e=>{if(e.target.dataset.adviceText)adviceDrafts.set(e.target.dataset.adviceText,e.target.value);if(e.target.id==='merge-search'){mergeQuery=e.target.value;renderMergeCandidates();}});
document.addEventListener('change',e=>{const el=e.target;if(modelFields.some(([,m])=>m===el.id)){settingsDirty=true;updateEfforts(false,el.id);}if(el.id==='inbox-from'||el.id==='inbox-until'){inboxFrom=$('#inbox-from').value;inboxUntil=$('#inbox-until').value;inboxPage=1;inboxSelected.clear();renderInbox();}if(el.id==='inbox-page-size'){inboxPageSize=Number(el.value);inboxPage=1;inboxSelected.clear();renderInbox();}if(el.dataset.inboxSelect){el.checked?inboxSelected.add(el.dataset.inboxSelect):inboxSelected.delete(el.dataset.inboxSelect);renderInbox();}if(el.id==='inbox-select-all'){for(const m of inboxRows())el.checked?inboxSelected.add(m.id):inboxSelected.delete(m.id);renderInbox();}if(el.name==='merge-choice'){mergeTarget=el.value;renderMergeCandidates();}if(el.id==='merge-confirm-environment')updateMergeButton();});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||!['settingsTarget','promptSection','adviceReply','adviceAction','inboxDelete','workflow'].some(k=>b.dataset[k]))return;try{
 if(b.dataset.settingsTarget){$('#settings-'+b.dataset.settingsTarget)?.scrollIntoView({block:'start',behavior:'smooth'});return;}
 if(b.dataset.promptSection){if(!await leaveSettings())return;settingsDirty=false;promptEditing=false;promptSection=['advice','memory'].includes(b.dataset.promptSection)?b.dataset.promptSection:'history';page='prompts';await render();return;}
 if(b.dataset.adviceReply){const key=b.dataset.adviceReply;adviceOpen.has(key)?adviceOpen.delete(key):adviceOpen.add(key);const box=b.closest('.advice-card').querySelector('.advice-composer');box.hidden=!adviceOpen.has(key);b.setAttribute('aria-expanded',adviceOpen.has(key));b.textContent='批复 '+(adviceOpen.has(key)?'▴':'▾');if(!box.hidden)box.querySelector('textarea').focus();return;}
 if(b.dataset.adviceAction){const {kind,id,adviceAction:action}=b.dataset,key=adviceKey(kind,id);if(adviceBusy.has(key))return;adviceBusy.add(key);b.disabled=true;try{if(action==='feedback'){const text=(adviceDrafts.get(key)||'').trim();if(!text)throw Error('请填写批复意见');renderLearning();await rpc('advice_feedback',{kind,id,text});adviceDrafts.delete(key);adviceOpen.delete(key);toast('建议已按批复修改，等待你启用');}else if(action==='retry')await rpc('prompt_retry',{id});else if(kind==='tag')await rpc('tag_decide',{action:'reject',id,expected:state.tag_state.versions.at(-1).id});else if(kind==='prompt'&&action==='enable')await rpc('prompt_adopt',{id});else await rpc('advice_decide',{kind,id,action});}finally{adviceBusy.delete(key);await refreshState(true);}return;}
 if(b.dataset.inboxDelete){confirmMessageDelete([b.dataset.inboxDelete]);return;}
 switch(b.dataset.workflow){case 'inbox-sort':inboxSort=inboxSort==='asc'?'desc':'asc';await renderInbox();break;case 'clear-time':inboxFrom='';inboxUntil='';$('#inbox-from').value='';$('#inbox-until').value='';renderInbox();break;case 'inbox-prev':inboxPage=Math.max(1,inboxPage-1);inboxSelected.clear();await renderInbox();break;case 'inbox-next':inboxPage=Math.min(inboxData.pages,inboxPage+1);inboxSelected.clear();await renderInbox();break;case 'inbox-jump':inboxPage=Math.max(1,Math.min(inboxData.pages,Number($('#inbox-page-jump').value)||1));inboxSelected.clear();await renderInbox();break;case 'retention-settings':page='settings';await render();$('#settings-storage')?.scrollIntoView({block:'start'});$('#cfg-retention').focus();break;case 'delete-selected':confirmMessageDelete([...inboxSelected]);break;case 'delete-messages':b.disabled=true;await rpc('messages_delete',{ids:deletingMessages});for(const id of deletingMessages)inboxSelected.delete(id);closeModal();inboxLoadedKey='';await refreshState(true);toast('消息已删除，关联事项保留');break;case 'handling-history':page='handling';await render();break;}
 }catch(err){if($('#modal-error')&&!$('#overlay').hidden)$('#modal-error').textContent=err.message;toast(err.message);}finally{if(!b.dataset.workflow?.startsWith('inbox-'))b.disabled=false;}});

// ---- Work state, calendar correction, steps and archive versions ----
const workLabels={working:'工作中',overtime:'加班中',off_duty:'已下班',holiday:'假期',calendar_unknown:'日历未知'};
function workStatusBar(){const ws=state?.work_state;if(!ws)return '<span class="helper">日历未就绪</span>';const cal=ws.calendar_day||{},status=ws.status||'calendar_unknown';const source={manual:'手动校正',cache:'holiday-cn 缓存',weekend:'周末规则'}[cal.source]||'无来源';const stale=cal.stale?' · 缓存已过期':'';const hint=`业务日 ${ws.business_date||'—'} · ${source}${stale}`;return `<button class="work-chip state-${esc(status)}" data-action="work-state" aria-haspopup="dialog" aria-controls="work-state-panel" title="${esc(hint)}">${esc(workLabels[status]||status)} · ${esc(ws.business_date||'—')}${status==='calendar_unknown'?' · 请确认':''}</button>${status==='working'?'':`<button class="quiet" data-action="overtime-toggle" title="加班只对当前业务日有效，下一业务日开始自动过期">${status==='overtime'?'结束加班':'开启加班'}</button>`}`;}
function closeWorkState(restore=false){const panel=$('#work-state-panel');if(panel)motionExit(panel);const button=$('[data-action="work-state"]');button?.setAttribute('aria-expanded','false');if(restore)button?.focus({preventScroll:true});}
function positionWorkState(){const panel=$('#work-state-panel'),button=$('[data-action="work-state"]');if(!panel||!button)return;const rect=button.getBoundingClientRect();panel.style.left=Math.max(12,Math.min(rect.right-panel.offsetWidth,innerWidth-panel.offsetWidth-12))+'px';panel.style.top=Math.max(12,Math.min(rect.bottom+8,innerHeight-panel.offsetHeight-12))+'px';}
function openWorkState(){if($('#work-state-panel')){closeWorkState(true);return;}closeBacklog();const ws=state?.work_state||{},cal=ws.calendar_day||{};const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'});const diagnostics=(cal.diagnostics||[]).map(d=>d.kind==='no_coverage'?'无可用日历缓存':d.kind==='stale_cache'?`缓存获取于 ${date(d.fetched_at_ms)}，已过期但仍可用`:d.kind).join('；');const panel=document.createElement('section');panel.id='work-state-panel';panel.className='backlog-panel work-state-panel';panel.setAttribute('role','dialog');panel.setAttribute('aria-label','工作状态');panel.innerHTML=`<div class="backlog-head"><h3>工作状态</h3><button class="quiet" data-work-close aria-label="关闭工作状态">×</button></div><div class="work-state-summary"><b>${esc(workLabels[ws.status]||'未知')}</b><span class="helper">业务日 ${esc(ws.business_date||'—')}</span></div><p>自动 AI 在工作或加班时执行。手动操作不受时段限制。</p>${ws.status==='working'?'<p>当前在工作时段内。</p>':`<button class="work-overtime" data-work-overtime="${ws.status==='overtime'?'0':'1'}">${ws.status==='overtime'?'结束加班':'开启加班'}</button><p>加班对当前业务日生效，下一业务日自动结束。</p>`}<details class="work-correction"><summary>校正日期</summary><div class="form-group"><label for="work-date">日期</label><input id="work-date" type="date" value="${esc(cal.date||today)}"></div><div class="form-group"><label for="work-kind">类型</label><select id="work-kind"><option value="workday">工作日 / 调休上班</option><option value="holiday" ${['holiday','weekend'].includes(cal.kind)?'selected':''}>假期 / 休息日</option></select></div><p>只影响所选日期，优先于日历缓存。</p><button class="primary" data-work-correct>保存校正</button></details><details><summary>日历详情</summary><p>日历日期 ${esc(cal.date||'—')} · ${esc({workday:'工作日',weekend:'周末',holiday:'假期',unknown:'未知'}[cal.kind]||'未知')}</p><p>来源 ${esc({manual:'手动校正',cache:'holiday-cn 缓存',weekend:'周末规则'}[cal.source]||'无')}${cal.publication_year?` · 发布年份 ${esc(cal.publication_year)}`:''}</p><p>${esc(diagnostics||(cal.kind==='unknown'?'没有可用日历缓存，请校正日期或开启加班。':cal.stale?'缓存已过期，将继续刷新。':'日历缓存正常。'))}</p></details><div id="work-state-error" class="error-box" role="status"></div>`;document.body.append(panel);$('[data-action="work-state"]')?.setAttribute('aria-expanded','true');positionWorkState();panel.querySelector('[data-work-close]').focus({preventScroll:true});panel.addEventListener('toggle',positionWorkState,true);}
async function applyWorkState(params,message){await rpc('work_state',params);closeWorkState(true);await refreshState(true);toast(message);}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#work-state-panel,[data-action="work-state"]'))closeWorkState();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#work-state-panel')){e.preventDefault();closeWorkState(true);}});
window.addEventListener('resize',positionWorkState);
window.addEventListener('blur',()=>closeWorkState());
function archiveAttemptHistory(attempts){return attempts.length?`<details class="report-disclosure"><summary>归档执行记录 <span>${attempts.length} 次</span></summary>${attempts.slice().reverse().map(a=>`<div class="source"><b>${esc(({succeeded:'归档完成',failed:'归档未完成',running:'归档处理中',queued:'等待归档'})[a.status]||a.status)}</b><div class="tiny">${esc(date(a.finished||a.started||a.created))}</div><p>已处理 ${a.processed||0} 条变更 · 已归档 ${a.archived_tasks||0} 个事项 · 剩余 ${a.remaining||0} 条</p>${a.error?`<p>${esc(a.error)}</p>`:''}</div>`).join('')}</details>`:'';}
async function openArchiveHistory(){const history=await rpc('archive_history');const versions=history.versions||[],attempts=archiveAttemptHistory(history.attempts||[]);if(!versions.length){setModal(`<h2>归档版本历史</h2>${attempts}<p class="helper">尚无归档版本。</p><div class="dialog-foot"><button data-action="close">关闭</button></div>`);return;}const rows=versions.slice().reverse().map(v=>`<div class="source"><div class="row"><b>${esc(v.action==='rollback'?'回滚版本':'归档版本')}</b><span class="tiny">${esc(date(v.created))}</span>${v.id===history.current?'<span class="badge green">当前</span>':''}</div><p class="helper">${esc(v.reason||'')}</p><button data-archive-view="${esc(v.id)}" ${v.id===history.current?'disabled':''}>比较并回滚到此版本</button></div>`).join('');setModal(`<h2>归档版本历史</h2>${attempts}<p class="helper">回滚只恢复提示词、规则和标签，保留当前 AI 记忆，不倒退消息进度，也不覆盖后续人工修改。</p>${rows}<div class="dialog-foot"><button data-action="close">关闭</button></div>`);}
async function compareArchiveVersion(id){const [history,target]=await Promise.all([rpc('archive_history'),rpc('archive_version',{id})]);const currentId=history.current;if(!currentId||currentId===id)throw Error('当前版本无需回滚');const current=await rpc('archive_version',{id:currentId});const block=(title,a,b)=>`<details><summary>${esc(title)}</summary><div class="cols"><pre style="white-space:pre-wrap">${esc(a||'（空）')}</pre><pre style="white-space:pre-wrap">${esc(b||'（空）')}</pre></div></details>`;const rules=x=>(x.rules||[]).map(r=>`${r.title}：${r.rule}`).join('\n');const tags=x=>(x.tags||[]).map(g=>`${g.name}：${(g.values||[]).join('、')}`).join('\n');const memory=x=>(x.memory||[]).map(m=>`${m.key}：${m.text}`).join('\n');setModal(`<h2>比较归档版本</h2><p class="helper">左侧当前版本，右侧目标版本。确认后追加一个新的回滚版本。</p>${block('系统提示词',current.prompt,target.prompt)}${block('启用规则',rules(current),rules(target))}${block('标签目录',tags(current),tags(target))}<p class="helper">AI 记忆保持当前内容，不参与版本比较或回滚。</p><div id="modal-error" class="error-box"></div><div class="dialog-foot"><button data-action="close">取消</button><button class="primary" data-archive-rollback="${esc(id)}" data-expected="${esc(currentId)}">确认回滚</button></div>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const mine=b.dataset.action==='work-state'||b.dataset.action==='overtime-toggle'||b.dataset.action==='archive-history'||b.hasAttribute('data-work-close')||b.hasAttribute('data-work-overtime')||b.hasAttribute('data-work-correct')||b.dataset.archiveView||b.dataset.archiveRollback;if(!mine)return;try{
if(b.hasAttribute('data-work-close')){closeWorkState(true);return;}
if(b.dataset.action==='work-state'){openWorkState();return;}
if(b.dataset.action==='overtime-toggle'){const on=state?.work_state?.status!=='overtime';b.disabled=true;await applyWorkState({overtime:on},on?'已开启加班':'已结束加班');return;}
if(b.hasAttribute('data-work-overtime')){b.disabled=true;await applyWorkState({overtime:b.dataset.workOvertime==='1'},b.dataset.workOvertime==='1'?'已开启加班':'已结束加班');return;}
if(b.hasAttribute('data-work-correct')){b.disabled=true;await applyWorkState({date:$('#work-date').value,kind:$('#work-kind').value},'日期校正已保存');return;}
if(b.dataset.action==='archive-history'){b.disabled=true;await openArchiveHistory();return;}
if(b.dataset.archiveView){b.disabled=true;await compareArchiveVersion(b.dataset.archiveView);return;}
if(b.dataset.archiveRollback){if(!confirm('确认回滚到此归档版本？只恢复提示词、规则和标签，保留当前 AI 记忆。'))return;b.disabled=true;await rpc('archive_rollback',{id:b.dataset.archiveRollback,expected:b.dataset.expected});closeModal();await refreshState(true);toast('已追加回滚版本');return;}
}catch(error){if($('#work-state-error'))$('#work-state-error').textContent=error.message;else if($('#modal-error'))$('#modal-error').textContent=error.message;toast(error.message);}finally{b.disabled=false;}});

let activeHelp=null,helpPinned=false;
function hideHelp(){motionExit(document.querySelector('.help-popover'));activeHelp?.setAttribute('aria-expanded','false');activeHelp=null;helpPinned=false;}
function positionHelp(){const box=document.querySelector('.help-popover');if(!box||!activeHelp?.isConnected){hideHelp();return;}const r=activeHelp.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight){hideHelp();return;}const b=box.getBoundingClientRect();box.style.left=Math.max(12,Math.min(r.left,innerWidth-b.width-12))+'px';box.style.top=(r.bottom+b.height+12<innerHeight?r.bottom+8:Math.max(12,r.top-b.height-8))+'px';}
function showHelp(el,pin=false){if(activeHelp===el){helpPinned=helpPinned||pin;positionHelp();return;}hideHelp();activeHelp=el;helpPinned=pin;const box=document.createElement('div');box.className='help-popover';box.id='help-popover';box.role='tooltip';box.textContent=el.dataset.help||el.dataset.tip||'';document.body.append(box);el.setAttribute('aria-expanded','true');el.setAttribute('aria-describedby',box.id);positionHelp();}
document.addEventListener('pointerover',e=>{const el=e.target.closest('.help-dot');if(el&&!helpPinned)showHelp(el);});
document.addEventListener('pointerout',e=>{if(activeHelp&&!helpPinned&&document.activeElement!==activeHelp&&e.target.closest('.help-dot'))hideHelp();});
document.addEventListener('focusin',e=>{const el=e.target.closest('.help-dot');if(el)showHelp(el);});
document.addEventListener('focusout',e=>{if(e.target.closest('.help-dot')&&!helpPinned)hideHelp();});
document.addEventListener('click',e=>{const el=e.target.closest('.help-dot');if(el){e.preventDefault();if(activeHelp===el&&helpPinned)hideHelp();else showHelp(el,true);}else hideHelp();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')hideHelp();});
window.addEventListener('resize',positionHelp);document.addEventListener('scroll',()=>{if(helpPinned||document.activeElement===activeHelp)positionHelp();else hideHelp();},true);
// Sender avatar: first character on a colour picked stably from the name, so the
// same person is recognisable at a glance across pages and sessions.
function senderAvatar(name){const text=String(name||'').trim(),tones=['blue','green','amber','red','violet'];let h=0;for(const c of text)h=(h*31+c.codePointAt(0))>>>0;return `<span class="sender-avatar tone-${tones[h%tones.length]}" aria-hidden="true">${esc([...text][0]||'?')}</span>`}
